[extensionOf(tableStr(SalesConfirmHeaderTmp))]
final class AVADAISalesConfirmHeaderTmp_tbl_Extension
{
}

Method.Source:
/// <summary>
/// displays customer information
/// </summary>
/// <returns><c>CustName</c> object.</returns>
display CustName AVADAIOrderName()
{
    CustConfirmJour     custConfirmJour;

    select OrderAccount from custConfirmJour where custConfirmJour.ConfirmId == this.ConfirmId;
    return CustTable::find(custConfirmJour.OrderAccount).name();
}

