/// <summary>
/// AVADAIDeliveryStreet
/// </summary>
/// <returns>CustAccount</returns>
display LogisticsAddressStreet AVADAIDeliveryStreet()
{
    CustConfirmJour             AVADAICustConfirmJour;
    LogisticsPostalAddress      AVADAILogisticsPostalAddress;

    select DeliveryPostalAddress from AVADAICustConfirmJour where AVADAICustConfirmJour.ConfirmId  == this.ConfirmId
            join Street from AVADAILogisticsPostalAddress where AVADAILogisticsPostalAddress.recid == AVADAICustConfirmJour.DeliveryPostalAddress;
    return AVADAILogisticsPostalAddress.Street;
}

